import { test } from 'node:test';
import assert from 'node:assert/strict';
import { extentOf } from '../src/extent.js';

test('the extent of a few footprints', () => {
  const features = [{ vertices: [[1, 5], [3, 2]] }, { vertices: [[-4, 7]] }];
  assert.deepEqual(extentOf(features), [-4, 2, 3, 7]);
});

test('two million vertices do not overflow the stack', () => {
  const vertices = Array.from({ length: 2_000_000 }, (_, i) => [i, 2 * i]);
  assert.deepEqual(extentOf([{ vertices }]), [0, 0, 1_999_999, 3_999_998]);
});
